from cardio_1 import a, G
# E11 — Diabète sucré de type 2 (E-06-Endocrinologie et métabolisme). Clés absentes du glossaire au 09.10.2026.
a('SSED', [('S', 'Société'), ('S', 'Suisse d’'), ('E', 'Endocrinologie et de'), ('D', 'Diabétologie')], 'Société suisse d’endocrinologie et de diabétologie', '<p>Société savante suisse (en allemand SGED) qui publie les recommandations nationales sur le traitement du diabète de type 2 (2023), le dépistage de l’insuffisance cardiaque chez le diabétique (2024) et l’aptitude à la conduite (2025).</p>')
a('SGED', [('S', 'Schweizerische'), ('G', 'Gesellschaft für'), ('E', 'Endokrinologie und'), ('D', 'Diabetologie')], 'Société suisse d’endocrinologie et de diabétologie (sigle allemand)', '<p>Sigle allemand de la SSED.</p>')
a('EASD', [('E', 'European (européenne)'), ('A', 'Association for'), ('S', 'the Study of (pour l’étude du)'), ('D', 'Diabetes (diabète)')], 'Association européenne pour l’étude du diabète', '<p>Société savante européenne de diabétologie, coautrice avec l’American Diabetes Association des consensus sur la prise en charge du diabète de type 2 (2022, 2026) ; ces textes sont recevables en Suisse au titre de l’EASD.</p>')
a('ADA/EASD', [('ADA', 'American Diabetes Association (association américaine du diabète)'), ('EASD', 'European Association for the Study of Diabetes (association européenne pour l’étude du diabète)')], 'Consensus conjoint de l’American Diabetes Association et de l’Association européenne pour l’étude du diabète', '<p>Rapport de consensus sur la prise en charge du diabète de type 2 de l’adulte, publié en 2006 puis mis à jour, la dernière fois le 2 octobre 2026 (Diabetologia et Diabetes Care). Ici, ADA ne désigne pas l’adénosine désaminase.</p>')
a('DPP-4', [('D', 'Dipeptidyl-'), ('P', 'Peptidase'), ('-4', 'de type 4')], 'Dipeptidyl-peptidase 4', '<p>Enzyme qui inactive rapidement les incrétines GLP-1 et GIP. Ses inhibiteurs (sitagliptine, linagliptine) prolongent l’action des incrétines endogènes.</p>', 'e11-d-idpp4')
a('SGLT1', [('S', 'Sodium-'), ('GL', 'GLucose'), ('T', 'coTransporteur'), ('1', 'de type 1')], 'Cotransporteur sodium-glucose de type 1', '<p>Principal transporteur intestinal du glucose ; il réabsorbe aussi une partie du glucose dans le tubule rénal. La dapagliflozine est plus de 1400 fois plus sélective pour le SGLT2 que pour le SGLT1.</p>')
a('MASLD', [('M', 'Metabolic dysfunction- (dysfonction métabolique)'), ('A', 'Associated (associée à une)'), ('S', 'Steatotic (stéatosique)'), ('L', 'Liver (du foie)'), ('D', 'Disease (maladie)')], 'Stéatose hépatique associée à une dysfonction métabolique', '<p>Stéatose hépatique avec au moins un facteur de risque cardiométabolique, après exclusion d’une consommation importante d’alcool ; elle touche plus de 70 % des diabétiques de type 2 (ADA/EASD 2026).</p>', 'e11-masld')
a('MODY', [('M', 'Maturity (de la maturité)'), ('O', 'Onset (début)'), ('D', 'Diabetes (diabète)'), ('Y', 'of the Young (du sujet jeune)')], 'Diabète de type adulte survenant chez le sujet jeune', '<p>Diabète monogénique par défaut de la sécrétion d’insuline, à transmission sur plusieurs générations ; à évoquer avant 30 ans chez un sujet mince sans auto-anticorps.</p>', 'e11-mody')
a('LADA', [('L', 'Latent (latent)'), ('A', 'Autoimmune (auto-immun)'), ('D', 'Diabetes (diabète)'), ('A', 'in Adults (de l’adulte)')], 'Diabète auto-immun latent de l’adulte', '<p>Diabète de type 1 d’apparition tardive et d’évolution lente, souvent pris pour un type 2 ; les auto-anticorps le confirment.</p>', 'e11-type1-lada')
a('GAD', [('G', 'Glutamic Acid (acide glutamique)'), ('A', ''), ('D', 'Decarboxylase (décarboxylase)')], 'Décarboxylase de l’acide glutamique', '<p>Enzyme cible d’auto-anticorps ; les anticorps anti-GAD signent un diabète auto-immun.</p>', 'e11-cpeptide')
a('IA2', [('IA', 'Insulinoma-Associated (associé à l’insulinome)'), ('2', 'antigène 2')], 'Antigène 2 associé à l’insulinome', '<p>Antigène cible d’auto-anticorps ; les anticorps anti-IA2 signent un diabète auto-immun.</p>', 'e11-cpeptide')
a('ZnT8', [('Zn', 'Zinc'), ('T', 'Transporteur'), ('8', 'de type 8')], 'Transporteur du zinc de type 8', '<p>Antigène cible d’auto-anticorps ; les anticorps anti-ZnT8 complètent les anticorps anti-GAD et anti-IA2.</p>', 'e11-cpeptide')
a('HGPO', [('H', 'Hyperglycémie'), ('G', ''), ('P', 'Provoquée par voie'), ('O', 'Orale')], 'Hyperglycémie provoquée par voie orale', '<p>Test de tolérance au glucose : 75 g de glucose par la bouche après un jeûne de 8 heures, glycémie à 2 heures ; diabète si ≥ 11,1 mmol/L.</p>', 'e11-hgpo')
a('NPH', [('N', 'Neutral (neutre)'), ('P', 'Protamine'), ('H', 'Hagedorn (du nom de H. C. Hagedorn)')], 'Insuline isophane de Hagedorn', '<p>Insuline humaine d’action intermédiaire, en suspension à mélanger avant l’injection ; la SSED ne la recommande plus comme insuline basale du diabète de type 2 en raison de son risque d’hypoglycémie.</p>', 'e11-d-insulines')
a('AMPK', [('AMP', 'Adénosine MonoPhosphate'), ('K', 'Kinase (activée par l’AMP)')], 'Protéine kinase activée par l’adénosine monophosphate', '<p>Capteur énergétique cellulaire ; une partie des effets de la metformine passe par son activation.</p>', 'e11-d-metformine')
a('GLUT2', [('GLU', 'GLUcose'), ('T', 'Transporteur'), ('2', 'de type 2')], 'Transporteur du glucose de type 2', '<p>Transporteur par lequel le glucose entre dans la cellule β, dont il est aussi le capteur.</p>')
a('GLUT4', [('GLU', 'GLUcose'), ('T', 'Transporteur'), ('4', 'de type 4')], 'Transporteur du glucose de type 4', '<p>Transporteur insulinodépendant du muscle et du tissu adipeux ; l’insuline le fait migrer vers la membrane.</p>')
a('IRS-1', [('I', 'Insulin (de l’insuline)'), ('R', 'Receptor (récepteur)'), ('S', 'Substrate (substrat)'), ('-1', 'de type 1')], 'Substrat du récepteur de l’insuline de type 1', '<p>Protéine phosphorylée par le récepteur de l’insuline ; elle relaie le signal vers la PI3K.</p>')
a('IRS-2', [('I', 'Insulin (de l’insuline)'), ('R', 'Receptor (récepteur)'), ('S', 'Substrate (substrat)'), ('-2', 'de type 2')], 'Substrat du récepteur de l’insuline de type 2', '<p>Relais du signal de l’insuline, comme IRS-1.</p>')
a('PI3K', [('PI', 'PhosphatIdylinositol'), ('3', '3-'), ('K', 'Kinase')], 'Phosphatidylinositol 3-kinase', '<p>Enzyme qui produit le phosphatidylinositol triphosphate et active AKT dans la cascade de l’insuline.</p>')
a('AKT', [('AKT', 'nom propre de la kinase, non développable lettre à lettre')], 'Kinase AKT', '<p>Kinase activée par la cascade de l’insuline ; elle fait migrer GLUT4 vers la membrane et inhibe FOXO1 dans le foie.</p>')
a('FOXO1', [('FOX', 'FOrkhead boX (boîte en fourche)'), ('O', 'sous-classe O'), ('1', 'membre 1')], 'Facteur de transcription forkhead box O1', '<p>Facteur qui active les gènes de la néoglucogenèse hépatique ; l’insuline l’inhibe et freine ainsi la production de glucose.</p>')
a('DCCT', [('D', 'Diabetes (diabète)'), ('C', 'Control and (contrôle et)'), ('C', 'Complications'), ('T', 'Trial (essai)')], 'Essai sur le contrôle du diabète et ses complications', '<p>Essai dont la méthode de dosage sert, avec celle de l’UKPDS, de référence à la standardisation de l’HbA1c exigée par la SSED pour le diagnostic.</p>')
a('UKPDS', [('U', 'United'), ('K', 'Kingdom (Royaume-Uni)'), ('P', 'Prospective (prospective)'), ('D', 'Diabetes (du diabète)'), ('S', 'Study (étude)')], 'Étude prospective britannique du diabète', '<p>Essai randomisé chez 5102 diabétiques de type 2 nouvellement diagnostiqués : le contrôle intensif a réduit les complications microvasculaires de 25 %, et le bénéfice a persisté jusqu’à 24 ans après l’essai.</p>', 'e11-memoire')
a('ACCORD', [('A', 'Action to'), ('C', 'Control'), ('C', 'Cardiovascular'), ('O', ''), ('R', 'Risk in'), ('D', 'Diabetes')], 'Essai ACCORD (2008)', '<p>Essai chez 10 251 diabétiques de type 2 à haut risque : viser une HbA1c inférieure à 6,0 % a augmenté la mortalité (rapport de risque 1,22) sans réduire les événements cardiovasculaires.</p>', 'e11-hypo')
a('DiRECT', [('Di', 'Diabetes (diabète)'), ('RE', 'REmission (rémission)'), ('C', 'Clinical (clinique)'), ('T', 'Trial (essai)')], 'Essai DiRECT de rémission du diabète (2018)', '<p>Essai britannique en premier recours : un programme de perte de poids a obtenu 46 % de rémissions à un an contre 4 %.</p>', 'e11-remission')
a('FLOW', [('FLOW', 'nom propre de l’essai rénal du sémaglutide, non développable lettre à lettre')], 'Essai FLOW (sémaglutide, 2024)', '<p>Essai chez 3533 diabétiques de type 2 avec maladie rénale chronique : le sémaglutide 1 mg par semaine a réduit de 24 % les événements rénaux majeurs et les décès cardiovasculaires (Perkovic, 2024).</p>', 'e11-mrc')
a('SOUL', [('SOUL', 'nom propre de l’essai cardiovasculaire du sémaglutide oral, non développable lettre à lettre')], 'Essai SOUL (sémaglutide oral, 2025)', '<p>Essai chez 9650 diabétiques de type 2 avec maladie athéroscléreuse ou rénale : le sémaglutide oral a réduit les événements cardiovasculaires majeurs (12,0 contre 13,8 %, rapport de risque 0,86).</p>', 'e11-d-aglp1')
a('SURPASS', [('SURPASS', 'nom propre du programme de phase 3 du tirzépatide, non développable lettre à lettre')], 'Programme SURPASS (tirzépatide)', '<p>Essais de phase 3 du tirzépatide dans le diabète de type 2 : baisse d’HbA1c d’environ 2 % contre placebo et perte de 7 à 9,5 kg.</p>', 'e11-d-tirzepatide')
a('SURPASS-CVOT', [('SURPASS', 'programme du tirzépatide'), ('CVOT', 'CardioVascular Outcome Trial (essai sur les événements cardiovasculaires)')], 'Essai SURPASS-CVOT (tirzépatide contre dulaglutide)', '<p>Chez des diabétiques de type 2 avec maladie athéroscléreuse, le tirzépatide a été non inférieur au dulaglutide pour les événements cardiovasculaires majeurs (rapport de risque 0,92).</p>', 'e11-d-tirzepatide')
a('ARMSS-T2D', [('ARMSS', 'Alliance of Randomized trials of Medicine versus Metabolic Surgery in Type 2 Diabetes (alliance d’essais randomisés comparant médecine et chirurgie métabolique)'), ('T2D', 'Type 2 Diabetes (diabète de type 2)')], 'Analyse groupée ARMSS-T2D', '<p>Regroupement d’essais randomisés : 37,5 % de rémissions à trois ans après chirurgie métabolique contre 2,6 % sous traitement médical (ADA/EASD 2026).</p>', 'e11-bariatrique')
a('ORIGIN', [('ORIGIN', 'Outcome Reduction with Initial Glargine INtervention (réduction des événements par une intervention initiale par glargine)')], 'Essai ORIGIN (insuline glargine)', '<p>Essai chez 12 537 participants à haut risque cardiovasculaire avec dysglycémie ou diabète de type 2 débutant ; la SSED le cite comme preuve de la sécurité cardiovasculaire de la glargine.</p>', 'e11-d-insulines')
a('DEVOTE', [('DEVOTE', 'nom propre de l’essai de sécurité cardiovasculaire de l’insuline dégludec, non développable lettre à lettre')], 'Essai DEVOTE (insuline dégludec)', '<p>Essai cité par la SSED comme preuve de la sécurité cardiovasculaire de l’insuline dégludec.</p>', 'e11-d-insulines')
a('QualiCCare', [('QualiCCare', 'nom propre d’une association suisse pour la qualité des soins aux malades chroniques, non développable lettre à lettre')], 'Association suisse QualiCCare', '<p>Association qui a publié en 2023 le guide pratique suisse, diffusé par la SSED, de prise en charge du pied diabétique selon le niveau de risque.</p>', 'e11-pied')
for code, rng in [('G1', '≥ 90'), ('G2', '60 à 89'), ('G3a', '45 à 59'), ('G3b', '30 à 44'), ('G4', '15 à 29'), ('G5', '&lt; 15')]:
    a(code, [('G', 'catégorie de DFG (Glomerular filtration rate)'), (code[1:], 'catégorie ' + code[1:])], 'Catégorie ' + code + ' du débit de filtration glomérulaire (KDIGO)', '<p>DFG estimé de ' + rng + ' mL/min/1,73 m².</p>', 'e11-mrc')
a('Galicia-Garcia', [('Galicia-Garcia', 'nom du premier auteur (Galicia-Garcia U.)')], 'Galicia-Garcia et collaborateurs, International Journal of Molecular Sciences 2020', '<p>Revue en accès libre sur la physiopathologie du diabète de type 2 : sécrétion d’insuline, insulinorésistance du muscle, du tissu adipeux et du foie, dyslipidémie et dysfonction endothéliale (PMID 32872570).</p>')
a('E-06-Endocrinologie et métabolisme', [('E', 'Endocrinologie (initiale de la spécialité)'), ('06', 'sixième fragment dans l’ordre de production'), ('Endocrinologie et métabolisme', 'nom littéral du fragment')], 'Fragment E-06-Endocrinologie et métabolisme de MEDINA', '<p>Sixième fragment de production de MEDINA, qui réunit les cours d’endocrinologie et de métabolisme (organisation/fragments.json), dont E11 — Diabète sucré de type 2.</p>')
